choose.otherwise:






            https://login.microsoftonline.com/{{purview-tenant-id}}/oauth2/v2.0/token
            POST

                application/x-www-form-urlencoded

            @{
                var form = new System.Collections.Generic.Dictionary {
                    { "grant_type", "urn:ietf:params:oauth:grant-type:jwt-bearer" },
                    { "client_id", "{{purview-client-id}}" },
                    { "client_secret", "{{purview-client-secret}}" },
                    { "assertion", (string)context.Variables["pvUserToken"] },
                    { "scope", "https://{{purview-graph-host}}/Content.Process.User https://{{purview-graph-host}}/ProtectionScopes.Compute.User https://{{purview-graph-host}}/ContentActivity.Write" },
                    { "requested_token_use", "on_behalf_of" }
                };
                return string.Join("&", form.Select(kv => System.Uri.EscapeDataString(kv.Key) + "=" + System.Uri.EscapeDataString(kv.Value)));
            }

        <set-variable name="pvGraphToken" value="@{
            try { return ((IResponse)context.Variables["pvOboResponse"]).Body.As()["access_token"]?.ToString() ?? ""; }
            catch { return ""; }
        }" />











            https://{{purview-graph-host}}/beta/me/dataSecurityAndGovernance/processContent
            POST

                @("Bearer " + (string)context.Variables["pvGraphToken"])


                application/json

            @{
                var id = context.RequestId.ToString();
                var now = DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ss");
                return new JObject(new JProperty("contentToProcess", new JObject(
                    new JProperty("contentEntries", new JArray(new JObject(
                        new JProperty("@odata.type", "#microsoft.graph.processConversationMetadata"),
                        new JProperty("identifier", id),
                        new JProperty("content", new JObject(
                            new JProperty("@odata.type", "#microsoft.graph.textContent"),
                            new JProperty("data", context.Variables.GetValueOrDefault("safetyText", "")))),
                        new JProperty("name", "AI Gateway Sandbox " + context.Variables.GetValueOrDefault("surface", "model") + " request"),
                        new JProperty("correlationId", id),
                        new JProperty("sequenceNumber", 0),
                        new JProperty("isTruncated", false),
                        new JProperty("createdDateTime", now),
                        new JProperty("modifiedDateTime", now)))),
                    new JProperty("activityMetadata", new JObject(new JProperty("activity", "uploadText"))),
                    new JProperty("protectedAppMetadata", new JObject(
                        new JProperty("name", "AI Gateway Sandbox"),
                        new JProperty("version", "1.0"),
                        new JProperty("applicationLocation", new JObject(
                            new JProperty("@odata.type", "#microsoft.graph.policyLocationApplication"),
                            new JProperty("value", "{{purview-client-id}}"))))),
                    new JProperty("integratedAppMetadata", new JObject(
                        new JProperty("name", "AI Gateway Sandbox"),
                        new JProperty("version", "1.0")))))).ToString();
            }




<set-variable name="pvStatus" value="@{
    try {
        var response = context.Variables.GetValueOrDefault("pvResponse");
        if (response == null || response.StatusCode >= 300) { return "unknown"; }
        var verdict = response.Body.As(preserveContent: true);
        var actions = verdict.SelectTokens("$.policyActions[*].action").Select(t => t.ToString()).ToList();
        return actions.Any(a => a.Equals("block", StringComparison.OrdinalIgnoreCase) || a.Equals("restrictAccess", StringComparison.OrdinalIgnoreCase) || a.Equals("blockAccess", StringComparison.OrdinalIgnoreCase)) ? "blocked" : "allowed";
    } catch { return "unknown"; }
}" />






            <dimension name="Model" value="@(context.Variables.GetValueOrDefault("surface", "model"))" />




                application/json


                dlp-blocked


                purview-dlp


                @((string)context.Variables["pvStatus"] == "blocked" ? "purview-dlp-policy" : "purview-verdict-unknown (fail closed)")


                @((context.Variables.GetValueOrDefault("safetyMicroUsd", 0) / 1000000.0).ToString("0.000000"))


                @(context.RequestId.ToString())

            @(new JObject(new JProperty("error", new JObject(
                new JProperty("code", "BlockedByDataLossPrevention"),
                new JProperty("message", "Microsoft Purview DLP blocked this request before it reached a model, tool or agent.")))).ToString())
